// Top K Frequent Elements using Min Heap of size K
var heap = AnimatedHeap<Int>(kind: .min)
let freqs = [3, 2, 1]
let k = 2

for f in freqs {
    heap.insert(f)
    if heap.count > k {
        heap.extract()
    }
}

var topK: [Int] = []
while !heap.isEmpty {
    if let f = heap.extract() {
        topK.append(f)
    }
}
